import{_ as o,o as t,c as i,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2019-09-04 :: Ceph Developer Monthly","description":"","frontmatter":{"title":"2019-09-04 :: Ceph Developer Monthly","date":"2019-09-04T00:00:00.000Z","updated":"2019-09-07T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可伸缩性","对象存储","块存储","文件系统存储","一致性","去中心化","性能","Bluestore","Bluefs","Rocksdb","OSD","MON","MDS","PG","Rados","Librados","Libcephfs","Cephfs","Rbd","Radosgw","RGW","RESTful API","认证","授权","加密","消息编码","复制","快照","克隆","虚拟化","云计算","AWS","Azure","Google Cloud","混合云","多云","存储集群","节点","存储","SSD","HDD","JBOD","SAN","NAS","网络","网络拓扑","失败域","恢复","弹性","负载均衡","缓存","压缩","去重","分层","性能调优","基准测试","验证"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-09-04_-_-_Ceph_Developer_Monthly.md","filePath":"posts/2019/2019-09-04_-_-_Ceph_Developer_Monthly.md","lastUpdated":1780460162000}'),s={name:"posts/2019/2019-09-04_-_-_Ceph_Developer_Monthly.md"};function r(n,l,p,g,_,a){return t(),i("div",null,[...l[0]||(l[0]=[e("<p>会议纪要</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： 多位Ceph研发人员</p><p><strong>会议主题</strong>：</p><ol><li><strong>返回写入缓冲区或数据</strong>： 讨论在写操作中记录返回值和输出缓冲区，以及如何处理输出缓冲区的内容。</li><li><strong>集群镜像简化</strong>： 讨论简化集群镜像设置的过程，以便于用户使用。</li></ol><p><strong>关键细节与讨论</strong>：</p><p><strong>1. 返回写入缓冲区或数据</strong></p><ul><li><strong>背景</strong>： 目前，Ceph只记录写操作的返回值，并显式清除输出缓冲区。这导致在某些情况下无法获取完整的操作信息。</li><li><strong>解决方案</strong>： <ul><li>在返回值旁边添加一个返回值长度字段。</li><li>更新OSD的解码器以填充该字段。</li><li>设置最大返回值长度为32字节。</li><li>提供配置选项以控制最大返回值长度。</li><li>在PG日志条目或dup日志条目中记录返回值。</li></ul></li><li><strong>担忧</strong>： <ul><li>需要确保输出缓冲区不会被填充随机数据。</li><li>需要考虑如何处理超出配置选项大小的缓冲区。</li></ul></li></ul><p><strong>2. 集群镜像简化</strong></p><ul><li><strong>背景</strong>： 为了简化Rook集群镜像设置，需要改进Ceph集群镜像功能。</li><li><strong>解决方案</strong>： <ul><li>提供一个命令，用于输出一个base64编码的JSON文件，包含集群信息。</li><li>在另一个集群上使用该命令导入JSON文件。</li><li>使用RBD镜像池和FSID来标识集群。</li><li>提供可选的集群友好名称。</li><li>支持单向和双向镜像。</li></ul></li><li><strong>讨论</strong>： <ul><li>是否需要在bootstrap步骤中创建临时用户。</li><li>是否需要在集群B上创建本地用户以进行通信。</li><li>如何跟踪集群模式（例如，图像模式和完整模式）。</li></ul></li></ul><p><strong>后续行动计划</strong>：</p><ul><li><strong>返回写入缓冲区或数据</strong>： <ul><li>完成代码更改，并添加配置选项。</li><li>在主分支上合并更改，并观察一段时间以确保没有问题。</li></ul></li><li><strong>集群镜像简化</strong>： <ul><li>完成CLI命令和API的更新。</li><li>完成文档更新。</li></ul></li><li><strong>其他事项</strong>： <ul><li>跟踪Ceph manager在启用新模块时重启的问题。</li><li>完成对象删除功能，删除所有克隆和快照。</li><li>统一Ceph monitor和daemon命令。</li></ul></li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了一些Ceph相关的英文关键词，如PG、OSD、RBD、monitor、daemon等。</li><li>会议讨论了一些计算机科学和Ceph领域的概念，如集群镜像、日志条目、配置选项等。</li></ul>",14)])])}const h=o(s,[["render",r]]);export{d as __pageData,h as default};
